@@ -0,0 +1,23 @@
+// Sites: each location belongs to one site; batches belong to the site of
+// their location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site of requests that do not name one. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** True when the location exists and belongs to `site`. */
+export function locationInSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && l.site === site);
+}
+
+/** True when the batch lies in a location of `site`. */
+export function batchInSite(store, batch, site) {
+  return locationInSite(store, batch.location, site);
+}
