+import test from "node:test";
+import assert from "node:assert/strict";
+import { memoryStore } from "../src/db/store.js";
+import { app, seed } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+// An annex batch of onion (item 1) in the annex fridge.
+function withAnnexStock() {
+  const data = seed();
+  data.batches.push({ id: 100, itemId: 1, lot: "AN-1", qty: 3, receivedOn: "2026-10-27", expires: "2026-10-30", location: "annex-fridge" });
+  data.seq.batch = 100;
+  return app(memoryStore(data));
+}
+
+test("the seed has the annex site and its fridge", () => {
+  const data = seed();
+  assert.equal(data.schemaVersion, 3);
+  assert.ok(data.sites.some((s) => s.id === "annex" && s.name === "Annex kitchen"));
+  const loc = data.locations.find((l) => l.id === "annex-fridge");
+  assert.deepEqual(loc, { id: "annex-fridge", name: "Annex fridge", tempC: 4, site: "annex" });
+  assert.ok(data.locations.filter((l) => l.id !== "annex-fridge").every((l) => l.site === "main"));
+});
+
+test("an unknown site is a 400 with its own code", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+  assert.match(res.body.error.message, /nowhere/);
+});
+
+test("without the header the site is main; the annex sees only its own stock", async () => {
+  const { handle } = withAnnexStock();
+  const main = await handle({ path: "/items" });
+  const other = await handle({ path: "/items", headers: annex });
+  assert.equal(main.body.find((i) => i.id === 1).onHand, 10);
+  assert.equal(other.body.find((i) => i.id === 1).onHand, 3);
+  assert.equal(other.body.find((i) => i.id === 2).onHand, 0);
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body.map((b) => b.id), [100]);
+  assert.ok((await handle({ path: "/batches" })).body.every((b) => b.id !== 100));
+  assert.equal((await handle({ path: "/batches/100" })).status, 404);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+});
+
+test("stock value and alerts follow the site", async () => {
+  const { handle } = withAnnexStock();
+  const value = (await handle({ path: "/reports/stock-value", headers: annex })).body;
+  assert.equal(value.totalCents, 3 * 180);
+  const alerts = (await handle({ path: "/alerts", headers: annex })).body;
+  assert.deepEqual(alerts.expiring.map((b) => b.id), [100]);
+});
+
+test("cooking in the annex cannot use main stock", async () => {
+  const { handle, store } = withAnnexStock();
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 4 } });
+  assert.equal(res.status, 409);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("stock-takes stay inside their site", async () => {
+  const { handle } = withAnnexStock();
+  const start = (headers, location) => handle({ method: "POST", path: "/stocktakes", headers, body: { location } });
+  assert.equal((await start({}, "annex-fridge")).status, 400);
+  assert.equal((await start(annex, "fridge")).body.error.code, "unknown_location");
+  const take = await start(annex, "annex-fridge");
